// Main page: add a bookmark, then browse/open saved bookmarks (US1 + US2).

import { useCallback, useEffect, useState } from "react";
import { AddBookmark } from "../components/AddBookmark";
import { BookmarkList } from "../components/BookmarkList";
import { EmptyState } from "../components/EmptyState";
import { listBookmarks, type Bookmark } from "../api/client";

export function App() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const list = await listBookmarks();
    setBookmarks(list.items);
    setLoaded(true);
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const handleSaved = useCallback(
    (bookmark: Bookmark, existing: boolean) => {
      setNotice(
        existing
          ? `Already saved — showing your existing bookmark for “${bookmark.title}”.`
          : `Saved “${bookmark.title}”.`
      );
      // Re-fetch shortly after so background-captured metadata (title/icon) shows.
      void refresh();
      setTimeout(() => void refresh(), 1500);
