  color: #1a1a1a;
}

body {
  margin: 0;
  background: #f6f7f9;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  font-size: 1.6rem;
}

.add-bookmark {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  align-items: center;
}

.add-bookmark input {
  flex: 1 1 320px;
  padding: 0.6rem 0.75rem;
  border: 1px solid #cfd4da;
  border-radius: 8px;
  font-size: 1rem;
}

.add-bookmark button {
  padding: 0.6rem 1.1rem;
  border: none;
  border-radius: 8px;
  background: #2f6feb;
  color: white;
  font-size: 1rem;
  cursor: pointer;
}

.add-bookmark button:disabled {
  opacity: 0.5;
  cursor: default;
}

.error {
  color: #c0392b;
  width: 100%;
  margin: 0.25rem 0 0;
}

.notice {
  color: #2f6feb;
  margin: 0.75rem 0;
}

.bookmark-list {
  list-style: none;
  padding: 0;
  margin: 1.25rem 0 0;
}

.bookmark-item {
  display: flex;
  gap: 0.6rem;
  padding: 0.75rem;
  background: white;
  border: 1px solid #e6e8eb;
  border-radius: 10px;
  margin-bottom: 0.6rem;
}

.favicon {
  margin-top: 0.2rem;
  flex: 0 0 16px;
}

.favicon--placeholder {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  background: #d8dde3;
}

.bookmark-body {
  min-width: 0;
}

.bookmark-title {
  font-weight: 600;
  color: #14315f;
  text-decoration: none;
}

.bookmark-title:hover {
  text-decoration: underline;
}

.bookmark-desc {
  margin: 0.2rem 0;
  color: #4a4f57;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.bookmark-url {
  font-size: 0.85rem;
  color: #8a9099;
  overflow-wrap: anywhere;
}

.empty-state {
  text-align: center;
  color: #6b727b;
  margin-top: 3rem;
}

/* Search + sort */
.search-bar {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  margin-top: 1.25rem;
  flex-wrap: wrap;
}

.search-input {
  flex: 1 1 320px;
  padding: 0.55rem 0.75rem;
  border: 1px solid #cfd4da;
  border-radius: 8px;
  font-size: 0.95rem;
}

.sort-control {
  font-size: 0.9rem;
  color: #4a4f57;
}

.sort-control select {
  padding: 0.4rem;
  border-radius: 6px;
  border: 1px solid #cfd4da;
}

/* Tag chips (shared) */
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.8rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  border: 1px solid #cfd4da;
  background: #eef1f5;
  color: #333;
  cursor: pointer;
}

.tag-chip--static {
  cursor: default;
  background: #e7f0ff;
  border-color: #cfe0ff;
  color: #14315f;
}

.tag-chip--selected {
  cursor: default;
  background: #e7f0ff;
}

.tag-chip--include {
  background: #d7f2dd;
  border-color: #9bd8ab;
  color: #14562a;
}

.tag-chip--exclude {
  background: #fbe0e0;
  border-color: #f0aeae;
  color: #7a1f1f;
}

.tag-remove {
  border: none;
  background: transparent;
  cursor: pointer;
  font-size: 0.9rem;
  line-height: 1;
  color: inherit;
