.tag-filter {
  display: flex;
  gap: 0.4rem;
  align-items: center;
  flex-wrap: wrap;
  margin: 0.6rem 0;
}

.tag-filter-label {
  font-size: 0.85rem;
  color: #4a4f57;
}

.tag-filter-hint {
  font-size: 0.72rem;
  color: #9098a1;
}

.bookmark-tags {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
  margin-top: 0.35rem;
}

/* List item actions */
.bookmark-item {
  align-items: flex-start;
}

.bookmark-actions {
  margin-left: auto;
  display: flex;
  gap: 0.4rem;
  flex-shrink: 0;
}

.bookmark-actions button,
.link-button {
  border: none;
  background: transparent;
  color: #2f6feb;
  cursor: pointer;
  font-size: 0.85rem;
  padding: 0.2rem 0.3rem;
}

.link-danger {
  color: #c0392b !important;
}

.no-results {
  color: #6b727b;
  margin-top: 2rem;
}

.active-filters {
  font-size: 0.85rem;
  color: #4a4f57;
  background: #f0f4fb;
  border: 1px solid #dbe6f7;
  border-radius: 8px;
  padding: 0.4rem 0.7rem;
  margin: 0.3rem 0 0.6rem;
}

/* Keep a busy item readable: tags wrap and never clip the description. */
.bookmark-desc {
  white-space: normal;
}

.bookmark-tags {
  max-width: 100%;
}

/* Header + toolbar */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.toolbar {
  display: flex;
  gap: 0.5rem;
}

.toolbar button {
  padding: 0.4rem 0.8rem;
  border: 1px solid #cfd4da;
  background: white;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
}

.muted {
  color: #6b727b;
  font-size: 0.88rem;
}

a.btn-primary,
a.btn-secondary {
  display: inline-block;
  text-decoration: none;
  text-align: center;
}

/* Export options */
.export-option {
  border: 1px solid #e6e8eb;
  border-radius: 10px;
  padding: 0.8rem;
  margin-top: 0.8rem;
}

.export-option-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.3rem;
}

.badge {
  font-size: 0.72rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
}

.badge--complete {
  background: #d7f2dd;
  color: #14562a;
}

.badge--lossy {
  background: #fdf0d5;
  color: #7a5a12;
}

/* View tabs */
.view-tabs {
  display: flex;
  gap: 0.25rem;
  margin: 1rem 0 0.5rem;
  border-bottom: 1px solid #e6e8eb;
}

.view-tab {
  border: none;
  background: transparent;
  padding: 0.5rem 0.9rem;
  cursor: pointer;
  font-size: 0.95rem;
  color: #6b727b;
  border-bottom: 2px solid transparent;
}

.view-tab--active {
  color: #14315f;
  font-weight: 600;
  border-bottom-color: #2f6feb;
}

/* Unread indicator */
.unread-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #2f6feb;
  margin-left: 0.4rem;
  vertical-align: middle;
}

.bookmark-item--unread .bookmark-title {
  font-weight: 700;
}

/* Tag input */
.tag-input-chips {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
  margin-bottom: 0.35rem;
}

.tag-input input {
  width: 100%;
  padding: 0.45rem;
  border: 1px solid #cfd4da;
  border-radius: 6px;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.modal {
  background: white;
  border-radius: 12px;
  padding: 1.25rem;
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow: auto;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.2);
}

.modal--small {
  max-width: 400px;
}

.modal label {
  display: block;
  margin-top: 0.75rem;
  font-size: 0.85rem;
  color: #4a4f57;
}

.modal input[type="text"],
.modal textarea {
  width: 100%;
