"""User Story 6 — bulk actions by ids and by filter (FR-018, SC-009)."""

from __future__ import annotations


def _make(client, url, title, tags=None):
    body = {"url": url, "title": title}
    if tags:
        body["tags"] = tags
    return client.post("/api/bookmarks", json=body).json()


def test_bulk_add_tag_by_ids(client):
    a = _make(client, "https://a.example", "A")
    b = _make(client, "https://b.example", "B")
    resp = client.post(
        "/api/bookmarks/bulk",
        json={"target": {"ids": [a["id"], b["id"]]}, "action": {"type": "add_tag", "tag": "keep"}},
    )
    assert resp.json() == {"affected": 2}
    items = client.get("/api/bookmarks").json()["items"]
    assert all("keep" in i["tags"] for i in items)


def test_bulk_archive_everything_matching_filter(client):
    _make(client, "https://a.example", "A", tags=["old-work"])
    _make(client, "https://b.example", "B", tags=["old-work"])
    _make(client, "https://c.example", "C", tags=["keep"])

    # "Select everything matching tag old-work" and archive it — no ids listed.
    resp = client.post(
        "/api/bookmarks/bulk",
        json={"target": {"filter": {"tags_any": ["old-work"]}}, "action": {"type": "archive"}},
    )
    assert resp.json() == {"affected": 2}
    # Main list now only has the "keep" one; the two old-work are archived.
    assert [i["title"] for i in client.get("/api/bookmarks").json()["items"]] == ["C"]
    assert client.get("/api/bookmarks", params={"archived": "true"}).json()["count"] == 2


def test_bulk_mark_unread_by_ids(client):
    a = _make(client, "https://a.example", "A")
    client.post(
        "/api/bookmarks/bulk",
        json={"target": {"ids": [a["id"]]}, "action": {"type": "mark_unread"}},
    )
    assert client.get("/api/bookmarks", params={"unread": "true"}).json()["count"] == 1


def test_bulk_delete_requires_confirmation(client):
    a = _make(client, "https://a.example", "A")
    unconfirmed = client.post(
        "/api/bookmarks/bulk",
        json={"target": {"ids": [a["id"]]}, "action": {"type": "delete"}},
    )
    assert unconfirmed.status_code == 400
    assert client.get("/api/bookmarks").json()["count"] == 1

    confirmed = client.post(
        "/api/bookmarks/bulk",
        json={"target": {"ids": [a["id"]]}, "action": {"type": "delete", "confirm": True}},
    )
    assert confirmed.json() == {"affected": 1}
    assert client.get("/api/bookmarks").json()["count"] == 0

// Typed client for the backend API (contracts/api.md).

export interface Bookmark {
  id: number;
  url: string;
  title: string;
  icon: string | null;
  description: string | null;
  notes: string | null;
  date_added: string;
  is_read: boolean;
  is_archived: boolean;
  tags: string[];
  existing?: boolean;
}

export interface BookmarkList {
  items: Bookmark[];
  count: number;
}

export interface SaveResult {
  bookmark: Bookmark;
  /** true when the URL was already saved and the existing one was returned */
  existing: boolean;
}

export type SortOrder = "recent" | "title";

export interface Filters {
  q?: string;
  tagsAny?: string[];
  tagsNot?: string[];
  sort?: SortOrder;
  unread?: boolean;
  archived?: boolean;
}

export class ApiError extends Error {}

export async function saveBookmark(url: string): Promise<SaveResult> {
  const resp = await fetch("/api/bookmarks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ url }),
  });
  if (resp.status === 422) {
    const body = await resp.json().catch(() => ({}));
    throw new ApiError(body.detail ?? "That doesn't look like a valid web address.");
  }
  if (!resp.ok) {
    throw new ApiError("Could not save the bookmark. Please try again.");
  }
  const bookmark: Bookmark = await resp.json();
  return { bookmark, existing: Boolean(bookmark.existing) };
}

export async function listBookmarks(filters: Filters = {}): Promise<BookmarkList> {
  const params = new URLSearchParams();
  if (filters.q) params.set("q", filters.q);
  (filters.tagsAny ?? []).forEach((t) => params.append("tags_any", t));
  (filters.tagsNot ?? []).forEach((t) => params.append("tags_not", t));
  if (filters.sort) params.set("sort", filters.sort);
  if (filters.unread) params.set("unread", "true");
  if (filters.archived) params.set("archived", "true");
  const resp = await fetch(`/api/bookmarks?${params.toString()}`);
  if (!resp.ok) {
    throw new ApiError("Could not load your bookmarks.");
  }
  return resp.json();
}

export interface BookmarkPatch {
  title?: string;
  description?: string | null;
  notes?: string | null;
  tags?: string[];
  is_read?: boolean;
  is_archived?: boolean;
}

export async function updateBookmark(id: number, patch: BookmarkPatch): Promise<Bookmark> {
  const resp = await fetch(`/api/bookmarks/${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(patch),
  });
  if (!resp.ok) {
    throw new ApiError("Could not save your changes.");
  }
  return resp.json();
}

export async function deleteBookmark(id: number): Promise<void> {
  const resp = await fetch(`/api/bookmarks/${id}`, { method: "DELETE" });
  if (!resp.ok) {
    throw new ApiError("Could not delete the bookmark.");
  }
}

export interface ImportResult {
  imported: number;
  skipped_duplicates: number;
}

export async function importBookmarks(file: File): Promise<ImportResult> {
  const form = new FormData();
  form.append("file", file);
  const resp = await fetch("/api/import", { method: "POST", body: form });
  if (!resp.ok) {
    throw new ApiError("Could not import that file.");
  }
  return resp.json();
}

/** URL for downloading an export in the given format. */
export function exportUrl(format: "html" | "json"): string {
  return `/api/export?format=${format}`;
}

export interface BulkFilter {
  q?: string;
  tags_any?: string[];
  tags_not?: string[];
  unread?: boolean;
  archived?: boolean;
}

export type BulkActionType =
  | "add_tag"
  | "archive"
  | "unarchive"
  | "mark_read"
  | "mark_unread"
  | "delete";

export async function bulkAction(
  target: { ids?: number[]; filter?: BulkFilter },
  action: { type: BulkActionType; tag?: string; confirm?: boolean }
): Promise<{ affected: number }> {
  const resp = await fetch("/api/bookmarks/bulk", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ target, action }),
  });
  if (!resp.ok) {
    throw new ApiError("Could not apply that action to the selected bookmarks.");
  }
  return resp.json();
}

export async function fetchTags(opts: { prefix?: string; inUse?: boolean } = {}): Promise<
  string[]
> {
  const params = new URLSearchParams();
  if (opts.prefix) params.set("prefix", opts.prefix);
  if (opts.inUse) params.set("in_use", "true");
  const resp = await fetch(`/api/tags?${params.toString()}`);
  if (!resp.ok) return [];
  return resp.json();
}

