}

.tag-filter-label {
  font-size: 0.85rem;
  color: #4a4f57;
}

.tag-filter-hint {
  font-size: 0.72rem;
  color: #9098a1;
}

.bookmark-tags {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
  margin-top: 0.35rem;
}

/* List item actions */
.bookmark-item {
