  border-bottom-color: #2f6feb;
}

/* Unread indicator */
.unread-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #2f6feb;
  margin-left: 0.4rem;
  vertical-align: middle;
}

.bookmark-item--unread .bookmark-title {
  font-weight: 700;
}

/* Bulk selection */
.bookmark-select {
  margin-top: 0.3rem;
  flex: 0 0 auto;
}

.bulk-bar {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  background: #14315f;
  color: white;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  margin: 0.5rem 0;
}

.bulk-count {
  font-weight: 600;
}

.bulk-bar .link-button {
  color: #bcd4ff;
}

.bulk-actions {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
  margin-left: auto;
  align-items: center;
}

.bulk-actions button {
  background: rgba(255, 255, 255, 0.15);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 0.35rem 0.6rem;
